//! A language's node path tables (decision 0722): what a step of a `node_path` is coded by, declared in each
//! language's source beside its other per-language tables (`Adapter::NODE_PATH`), generated by `rerail-engine
//! node-path-table` and checked in.
//!
//! A step says which child of its parent a path takes. A **slot** is a parent kind and one of its fields, or its
//! children in no field. A step is its slot, coded at a fixed width over the parent kind's slots here; then, in a
//! **kind-grouped** slot (a list of statements, or a field that holds several children), the child's kind, gamma coded
//! by its rank here, and its ordinal among its siblings of that kind; in any other slot, its ordinal, only where the
//! node's slot holds more than one child. A slot or kind not here takes an escape, so a table out of date makes a path
//! longer, never wrong.
//!
//! The lists are complete: each slot and kind the grammar's node types allow, the most frequent in a sample first.

/// A parent kind's slots, most frequent first.
#[derive(Clone, Copy, Debug)]
pub struct PathParent {
    pub kind: &'static str,
    pub slots: &'static [PathSlot],
}

/// A slot of a parent kind: a field, or `""` for the children in no field.
#[derive(Clone, Copy, Debug)]
pub struct PathSlot {
    pub field: &'static str,
    /// Its children are told apart by kind, then by ordinal among their kind (a list of statements; a field that holds
    /// several children).
    pub grouped: bool,
    /// A kind-grouped slot's kinds, most frequent first; empty for any other.
    pub kinds: &'static [&'static str],
}

/// A language's tables: its slots (generated), the kinds whose children are a list of statements and its labels
/// (written by hand, read by the generator and the spelling).
#[derive(Clone, Copy, Debug)]
pub struct PathTables {
    pub parents: &'static [PathParent],
    /// The kinds whose children in no field are a list of statements: kind-grouped (`node-path-table` reads them).
    pub lists: &'static [&'static str],
    /// The language's labels for kinds and fields, where the generic rule's (`label`) is wrong or long: `(name,
    /// label)`, a field's name prefixed with `.` (`.consequence`).
    pub labels: &'static [(&'static str, &'static str)],
}

impl PathTables {
    pub const EMPTY: PathTables = PathTables { parents: &[], lists: &[], labels: &[] };
}

/// The suffixes tree-sitter grammars share that a kind's label drops (`if_statement` is `if`).
const KIND_SUFFIXES: [&str; 7] = ["_statement", "_expression", "_definition", "_declaration", "_item", "_clause", "_function"];

/// Fields the grammars share, shortened.
const FIELD_LABELS: [(&str, &str); 7] = [
    ("consequence", "then"),
    ("alternative", "else"),
    ("condition", "cond"),
    ("arguments", "args"),
    ("parameters", "params"),
    ("return_type", "returns"),
    ("type_parameters", "tparams"),
];

/// A kind's label in `tables`' language: its own label there, else the kind with one shared suffix dropped.
pub fn kind_label(tables: &PathTables, kind: &'static str) -> &'static str {
    if let Some(&(_, l)) = tables.labels.iter().find(|(n, _)| *n == kind) {
        return l;
    }
    KIND_SUFFIXES.iter().find_map(|s| kind.strip_suffix(s).filter(|k| !k.is_empty())).unwrap_or(kind)
}

/// A field's label in `tables`' language: its own label there (`.field`), else the shared short name, else the field.
pub fn field_label(tables: &PathTables, field: &'static str) -> &'static str {
    if let Some(&(_, l)) = tables.labels.iter().find(|(n, _)| n.strip_prefix('.') == Some(field)) {
        return l;
    }
    FIELD_LABELS.iter().find(|(f, _)| *f == field).map_or(field, |(_, l)| l)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn labels_drop_a_shared_suffix_and_shorten_shared_fields() {
        let t = PathTables { parents: &[], lists: &[], labels: &[("expression_statement", "expr"), (".body", "do")] };
        assert_eq!(kind_label(&t, "if_statement"), "if");
        assert_eq!(kind_label(&t, "call_expression"), "call");
        assert_eq!(kind_label(&t, "function_item"), "function");
        assert_eq!(kind_label(&t, "expression_statement"), "expr", "the language's own label first");
        assert_eq!(kind_label(&t, "_statement"), "_statement", "nothing is left of a bare suffix");
        assert_eq!(kind_label(&t, "identifier"), "identifier");
        assert_eq!(field_label(&t, "consequence"), "then");
        assert_eq!(field_label(&t, "body"), "do");
        assert_eq!(field_label(&t, "name"), "name");
    }
}
